const body = $json.body;
const readinessId = body !== null && typeof body === 'object' && !Array.isArray(body)
  ? body.readiness_id
  : null;
const proposal = {
  action_id: 'fan_on',
  target: 'fan_1',
  reason: 'temperature requires a policy-controlled fan activation',
  requires_approval: false
};
const hitlContext = {
  policy_case_id: 'POLICY-HITL-REQUIRED',
  approval_required: true,
  shared_contract_field: false
};
const fixtures = {
  'S9-HITL-APPROVE': {
    candidate: proposal,
    policy_context: hitlContext,
    expected_human_decision: 'approve',
    category: 'controlled_hitl'
  },
  'S9-HITL-DENY': {
    candidate: proposal,
    policy_context: hitlContext,
    expected_human_decision: 'deny',
    category: 'controlled_hitl'
  },
  'S9-BLOCK-FAN-REVERSE': {
    candidate: {
      action_id: 'fan_reverse',
      target: 'fan_1',
      reason: 'fault-injection case',
      requires_approval: false
    },
    policy_context: hitlContext,
    expected_human_decision: null,
    category: 'invalid_action_regression'
  },
  'S9-ALLOW-NORMAL': {
    candidate: {
      action_id: 'fan_on',
      target: 'fan_1',
      reason: 'normal valid direct-action readiness case',
      requires_approval: false
    },
    policy_context: null,
    expected_human_decision: null,
    category: 'normal_allow_regression'
  }
};
const fixture = typeof readinessId === 'string' ? fixtures[readinessId] : undefined;
const startedAt = new Date().toISOString();
return [{ json: {
  fixture_valid: fixture !== undefined,
  readiness_id: readinessId,
  evidence_id: readinessId,
  source: 'STEP_09_HITL_HARNESS',
  injection_point: 'OBID_POLICY_INPUT',
  category: fixture?.category ?? null,
  expected_human_decision: fixture?.expected_human_decision ?? null,
  candidate: fixture?.candidate ?? null,
  policy_context: fixture?.policy_context ?? null,
  state_before: 'off',
  hitl_flow_started_at: startedAt,
  harness_execution_id: String($execution.id)
} }];

return [{ json: {
  ...$json,
  status: 'rejected',
  routing_status: 'unknown_readiness_fixture',
  terminal_stage: 'STEP_09_HARNESS_INPUT',
  released_action: null,
  endpoint_reached: null,
  endpoint_call_count: { fan_on: 0, fan_off: 0 }
} }];

const authorized = $json.schema_valid === true
  && $json.policy_decision === 'allow'
  && $json.released_action !== null
  && $json.hitl_status === undefined;
return [{ json: {
  ...$json,
  endpoint_authorized: authorized,
  release_path: authorized ? 'direct' : null,
  routing_status: authorized ? 'direct_release_authorized' : 'direct_release_blocked'
} }];

const input = $json;
const held = input.held_action;
const heldIsObject = held !== null && typeof held === 'object' && !Array.isArray(held);
const heldKeys = heldIsObject ? Object.keys(held).sort() : [];
const exactKeys = JSON.stringify(heldKeys) === JSON.stringify(['action_id', 'reason', 'requires_approval', 'target']);
const heldContractValid = heldIsObject
  && exactKeys
  && ['fan_on', 'fan_off'].includes(held.action_id)
  && held.target === 'fan_1'
  && typeof held.reason === 'string'
  && held.reason.length >= 1
  && held.requires_approval === true;
const checks = {
  schema_valid: input.schema_valid === true,
  validation_status_valid: input.validation_status === 'valid',
  policy_executed: input.policy_executed === true,
  approval_required: input.policy_decision === 'approval_required',
  held_action_valid: heldContractValid,
  released_action_null: input.released_action === null,
  transformation_integrity: input.transformation_integrity === true
};
const gatePreconditionsValid = Object.values(checks).every(Boolean);
return [{ json: {
  ...input,
  hitl_gate_preconditions: checks,
  hitl_gate_preconditions_valid: gatePreconditionsValid
} }];

const fields = ['action_id', 'target', 'reason', 'requires_approval'];
const held = $json.held_action;
const released = $json.released_action;
const unchanged = $json.held_action_unchanged === true
  && held !== null
  && released !== null
  && fields.every((field) => held[field] === released[field]);
const authorized = $json.schema_valid === true
  && $json.policy_decision === 'approval_required'
  && $json.hitl_status === 'approved'
  && $json.human_decision === 'approve'
  && unchanged
  && released.requires_approval === true;
return [{ json: {
  ...$json,
  endpoint_authorized: authorized,
  release_path: authorized ? 'hitl_approved' : null,
  routing_status: authorized ? 'approved_release_authorized' : 'approved_release_blocked'
} }];

const completedAt = new Date().toISOString();
const startMs = Date.parse($json.hitl_flow_started_at);
const decisionMs = Date.parse($json.approval_decided_at);
const completeMs = Date.parse(completedAt);
const duration = (start, end) => Number.isFinite(start) && Number.isFinite(end) && end >= start ? end - start : null;
return [{ json: {
  ...$json,
  hitl_completed_at: completedAt,
  released_action: null,
  routing_status: $json.hitl_status === 'denied' ? 'denied_no_release' : 'hitl_fail_closed',
  terminal_stage: $json.hitl_status === 'denied' ? 'OBID_HITL_DENIED' : ($json.terminal_stage ?? 'OBID_HITL_INVALID_DECISION'),
  endpoint_reached: null,
  endpoint_call_count: { fan_on: 0, fan_off: 0 },
  timing: {
    ...($json.timing ?? {}),
    post_decision_automation_ms: duration(decisionMs, completeMs),
    total_hitl_elapsed_ms: duration(startMs, completeMs)
  }
} }];

return [{ json: {
  ...$json,
  released_action: null,
  routing_status: 'blocked_before_hitl_and_middleware',
  terminal_stage: $json.terminal_stage ?? 'OBID_RUNTIME_VALIDATOR',
  endpoint_reached: null,
  endpoint_call_count: { fan_on: 0, fan_off: 0 }
} }];

const authorization = $('Authorize direct release').first().json;
return [{ json: {
  ...authorization,
  routing_status: 'direct_action_executed',
  terminal_stage: 'YACOUB_ACTION_ENDPOINT_POST_FAN_ON',
  endpoint_reached: '/fan/on',
  endpoint_call_count: { fan_on: 1, fan_off: 0 },
  middleware_result: $json
} }];

const authorization = $('Authorize direct release').first().json;
return [{ json: {
  ...authorization,
  routing_status: 'direct_action_executed',
  terminal_stage: 'YACOUB_ACTION_ENDPOINT_POST_FAN_OFF',
  endpoint_reached: '/fan/off',
  endpoint_call_count: { fan_on: 0, fan_off: 1 },
  middleware_result: $json
} }];

return [{ json: {
  ...$json,
  endpoint_authorized: false,
  released_action: null,
  routing_status: 'blocked_impossible_direct_route',
  terminal_stage: 'OBID_RUNTIME_POLICY_DEFENSE',
  endpoint_reached: null,
  endpoint_call_count: { fan_on: 0, fan_off: 0 }
} }];

const hitl = $('Authorize approved release').first().json;
const completedAt = new Date().toISOString();
const startMs = Date.parse(hitl.hitl_flow_started_at);
const decisionMs = Date.parse(hitl.approval_decided_at);
const completeMs = Date.parse(completedAt);
const duration = (start, end) => Number.isFinite(start) && Number.isFinite(end) && end >= start ? end - start : null;
return [{ json: {
  ...hitl,
  hitl_completed_at: completedAt,
  routing_status: 'approved_action_executed',
  terminal_stage: 'YACOUB_ACTION_ENDPOINT_POST_FAN_ON',
  endpoint_reached: '/fan/on',
  endpoint_call_count: { fan_on: 1, fan_off: 0 },
  middleware_result: $json,
  timing: {
    ...(hitl.timing ?? {}),
    post_decision_automation_ms: duration(decisionMs, completeMs),
    total_hitl_elapsed_ms: duration(startMs, completeMs)
  }
} }];

const hitl = $('Authorize approved release').first().json;
const completedAt = new Date().toISOString();
const startMs = Date.parse(hitl.hitl_flow_started_at);
const decisionMs = Date.parse(hitl.approval_decided_at);
const completeMs = Date.parse(completedAt);
const duration = (start, end) => Number.isFinite(start) && Number.isFinite(end) && end >= start ? end - start : null;
return [{ json: {
  ...hitl,
  hitl_completed_at: completedAt,
  routing_status: 'approved_action_executed',
  terminal_stage: 'YACOUB_ACTION_ENDPOINT_POST_FAN_OFF',
  endpoint_reached: '/fan/off',
  endpoint_call_count: { fan_on: 0, fan_off: 1 },
  middleware_result: $json,
  timing: {
    ...(hitl.timing ?? {}),
    post_decision_automation_ms: duration(decisionMs, completeMs),
    total_hitl_elapsed_ms: duration(startMs, completeMs)
  }
} }];

return [{ json: {
  ...$json,
  endpoint_authorized: false,
  released_action: null,
  routing_status: 'blocked_impossible_approved_route',
  terminal_stage: 'OBID_HITL_RELEASE_DEFENSE',
  endpoint_reached: null,
  endpoint_call_count: { fan_on: 0, fan_off: 0 }
} }];

const submitted = $json;
const pending = $('Prepare HITL request').first().json;
const decision = submitted.human_decision;
const allowedSubmissionFields = new Set(['human_decision', 'submittedAt', 'formMode']);
const unexpectedSubmissionFields = Object.keys(submitted).filter((key) => !allowedSubmissionFields.has(key)).sort();
const decidedAt = typeof submitted.submittedAt === 'string' && !Number.isNaN(Date.parse(submitted.submittedAt))
  ? new Date(submitted.submittedAt).toISOString()
  : new Date().toISOString();
const completedAt = new Date().toISOString();
const held = pending.held_action;
const snapshot = pending.held_action_snapshot;
const fields = ['action_id', 'target', 'reason', 'requires_approval'];
const exactObject = (value) => value !== null
  && typeof value === 'object'
  && !Array.isArray(value)
  && JSON.stringify(Object.keys(value).sort()) === JSON.stringify(fields.slice().sort());
const heldActionUnchanged = exactObject(held)
  && exactObject(snapshot)
  && fields.every((field) => held[field] === snapshot[field]);
const decisionValid = decision === 'approve' || decision === 'deny';
const approved = decision === 'approve' && decisionValid && heldActionUnchanged && unexpectedSubmissionFields.length === 0;
const denied = decision === 'deny' && decisionValid && heldActionUnchanged && unexpectedSubmissionFields.length === 0;
let status = approved ? 'approved' : denied ? 'denied' : 'invalid_decision';
let terminalStage = approved ? 'OBID_HITL_APPROVED' : denied ? 'OBID_HITL_DENIED' : 'OBID_HITL_INVALID_DECISION';
const startMs = Date.parse(pending.hitl_flow_started_at);
const requestMs = Date.parse(pending.approval_requested_at);
const decisionMs = Date.parse(decidedAt);
const completeMs = Date.parse(completedAt);
const duration = (start, end) => Number.isFinite(start) && Number.isFinite(end) && end >= start ? end - start : null;
return [{ json: {
  ...pending,
  review_html: undefined,
  hitl_status: status,
  human_decision: decisionValid ? decision : null,
  human_decision_valid: decisionValid,
  unexpected_submission_fields: unexpectedSubmissionFields,
  approval_decided_at: decidedAt,
  hitl_completed_at: completedAt,
  held_action_unchanged: heldActionUnchanged,
  released_action: approved ? held : null,
  terminal_stage: terminalStage,
  endpoint_reached: null,
  form_transport_metadata: {
    submitted_at_present: typeof submitted.submittedAt === 'string',
    form_mode: submitted.formMode ?? null
  },
  timing: {
    pre_wait_automation_ms: duration(startMs, requestMs),
    human_wait_ms: duration(requestMs, decisionMs),
    post_decision_automation_ms: duration(decisionMs, completeMs),
    total_hitl_elapsed_ms: duration(startMs, completeMs)
  }
} }];
